class C1:
    def __init__(self, p, tag):
        self.p = p
        self.tag = tag
    def __eq__(self, other):
        return self.p == other.p
    def __lt__(self, other):
        return self.p < other.p
    def __le__(self, other):
        return self.p <= other.p

x = C1(-6, 'x')
y = C1(6, 'y')
print(x == y, x != y, x < y, x <= y)

class C1:
    def __init__(self):
        self._d = {'k1': (9 | 30)}
    def __getitem__(self, key):
        return self._d[key]
    def __setitem__(self, key, val):
        self._d[key] = val
    def __len__(self):
        return len(self._d)

inst = C1()
v_read = inst['k1']
inst['k2'] = (2 * -1)
inst['k3'] = 1
print(v_read, inst['k2'], inst['k3'], len(inst))

