class C1:
    def __init__(self, val):
        self.val = val
    def __str__(self):
        return 'elem:' + str(self.val)
    def __repr__(self):
        return '<' + 'elem' + ' ' + str(self.val) + '>'

obj = C1(-2)
print(str(obj), repr(obj))

class C1:
    def __init__(self, target):
        self.target = target
    def __contains__(self, item):
        return item == self.target

box = C1(11)
print(11 in box, 18 in box, 18 not in box)
